/** Lexical analysis for the arithmetic expression language. */

/** Failure raised anywhere in the expression pipeline. */
export class ExprError extends Error {
  /**
   * @param {string} message reason, ending with the position it refers to
   * @param {number} index 0-based index into the source, in UTF-16 code units
   */
  constructor(message, index) {
    super(message);
    this.name = 'ExprError';
    this.index = index;
  }
}

const NUMBER_RE = /^(?:\d+(?:\.\d+)?|\.\d+)(?:[eE][+-]?\d+)?$/;

/** Greedily consume everything that could plausibly belong to a numeric literal. */
function scanNumberSpan(input, start) {
  let j = start;
  const n = input.length;
  while (j < n) {
    const c = input[j];
    if (/[0-9a-zA-Z.]/.test(c)) {
      j += 1;
      continue;
    }
    if ((c === '+' || c === '-') && j > start && /[eE]/.test(input[j - 1])) {
      j += 1;
      continue;
    }
    break;
  }
  return input.slice(start, j);
}

/**
 * Split an expression into tokens.
 *
 * @param {string} input expression source
 * @returns {{ type: 'number' | 'name' | 'operator' | 'lparen' | 'rparen' | 'comma', value: number | string, index: number }[]}
 *   tokens in source order
 */
export function tokenize(input) {
  const tokens = [];
  const n = input.length;
  let i = 0;
  while (i < n) {
    const c = input[i];
    if (/\s/.test(c)) {
      i += 1;
      continue;
    }
    if (/[0-9]/.test(c) || (c === '.' && i + 1 < n && /[0-9]/.test(input[i + 1]))) {
      const start = i;
      const span = scanNumberSpan(input, i);
      i += span.length;
      if (!NUMBER_RE.test(span)) {
        throw new ExprError(`malformed number at ${start}`, start);
      }
      tokens.push({ type: 'number', value: Number(span), index: start });
      continue;
    }
    if (/[A-Za-z_]/.test(c)) {
      const start = i;
      let j = i + 1;
      while (j < n && /[A-Za-z0-9_]/.test(input[j])) j += 1;
      tokens.push({ type: 'name', value: input.slice(start, j), index: start });
      i = j;
      continue;
    }
    if (c === '+' || c === '-' || c === '*' || c === '/' || c === '%' || c === '^') {
      tokens.push({ type: 'operator', value: c, index: i });
      i += 1;
      continue;
    }
    if (c === '(') {
      tokens.push({ type: 'lparen', value: c, index: i });
      i += 1;
      continue;
    }
    if (c === ')') {
      tokens.push({ type: 'rparen', value: c, index: i });
      i += 1;
      continue;
    }
    if (c === ',') {
      tokens.push({ type: 'comma', value: c, index: i });
      i += 1;
      continue;
    }
    const codePoint = input.codePointAt(i);
    const char = String.fromCodePoint(codePoint);
    throw new ExprError(`unexpected character '${char}' at ${i}`, i);
  }
  return tokens;
}
