            `function ${node.name} expects ${entry.arity} ${plural(entry.arity)}, got ${args.length} at ${node.index}`,
            node.index,
          );
        }
      } else if (args.length < entry.minArity) {
        throw new ExprError(
          `function ${node.name} expects at least ${entry.minArity} ${plural(entry.minArity)}, got ${args.length} at ${node.index}`,
          node.index,
        );
      }
      const result = entry.fn(...args);
      if (!Number.isFinite(result)) throw new ExprError(`non-finite result at ${node.index}`, node.index);
      return result;
    }
    default:
      throw new ExprError(`unknown node type: ${node.type} at ${node.index}`, node.index);
  }
}

